// Independent, encrypted Auto Password queues.
//
// This module deliberately only accepts accounts supplied by a Manage Server
// operator or accounts already generated by this bot. It never attempts to
// discover credentials, bypass a login, or process an account without a
// session cookie supplied by the authorized account-management system.
import {
  createCipheriv,
  createDecipheriv,
  createHash,
  randomUUID,
  randomBytes,
} from 'node:crypto';
import {
  readFileSync,
  renameSync,
  writeFileSync,
} from 'node:fs';
import { join } from 'node:path';
import {
  AttachmentBuilder,
  EmbedBuilder,
  ActionRowBuilder,
  ButtonBuilder,
  ButtonStyle,
  PermissionFlagsBits,
} from 'discord.js';
import { changePassword, verifyPasswordChange } from '../roblox.js';
import { findAccountByUsername } from '../bloxgen-dashboard.js';
import { getUpdatedAccount, setUpdatedAccount } from './account-credentials.js';
import { recordPasswordChange } from './account-history.js';
import {
  getAutoPasswordConfig,
  getDeliveryChannel,
  getNewPasswordChannel,
  getHealthChannel,
} from './settings.js';
import { ROOT, SESSION_SECRET } from '../config.js';

export const AUTO_PASSWORD_TYPES = [
  { id: 'alts', label: 'Alts', aliases: ['alt', 'alts'] },
  { id: '30d', label: '30+ Days', aliases: ['+30 days old', '30+ days', '30d', '30 days'] },
  { id: '1y', label: '1 Year+', aliases: ['+1 year old', '1 year+', '1y', '1 year'] },
  { id: '5y', label: '5 Years+', aliases: ['5+ years old', '5 years+', '5y', '5 years'] },
  { id: 'dump', label: 'Dump', aliases: ['dump'] },
  { id: 'custom', label: 'Custom', aliases: ['custom'] },
];

const FILE = join(ROOT, 'auto-password-state.json');
const KEY = SESSION_SECRET
  ? createHash('sha256').update(SESSION_SECRET).digest()
  : null;
const DEFAULT_STATE = { guilds: {} };
const workers = new Map();
const waiters = new Map();
let state = loadState();

function loadState() {
  try {
    const record = JSON.parse(readFileSync(FILE, 'utf8'));
    if (!KEY) return { ...DEFAULT_STATE };
    const decipher = createDecipheriv(
      'aes-256-gcm',
      KEY,
      Buffer.from(record.iv, 'base64'),
    );
    decipher.setAuthTag(Buffer.from(record.authTag, 'base64'));
    return JSON.parse(Buffer.concat([
      decipher.update(Buffer.from(record.ciphertext, 'base64')),
      decipher.final(),
    ]).toString('utf8'));
  } catch {
    return { ...DEFAULT_STATE };
  }
}

function saveState() {
  if (!KEY) {
    throw new Error('SESSION_SECRET is required to store Auto Password data securely.');
  }
  const iv = randomBytes(12);
  const cipher = createCipheriv('aes-256-gcm', KEY, iv);
  const ciphertext = Buffer.concat([
    cipher.update(JSON.stringify(state), 'utf8'),
    cipher.final(),
  ]);
  const temporary = `${FILE}.tmp`;
  writeFileSync(temporary, JSON.stringify({
    iv: iv.toString('base64'),
    authTag: cipher.getAuthTag().toString('base64'),
    ciphertext: ciphertext.toString('base64'),
  }, null, 2), { mode: 0o600 });
  renameSync(temporary, FILE);
}

function requireSecureStorage() {
  if (!KEY) {
    throw new Error('SESSION_SECRET is required before Auto Password can store credentials securely.');
  }
}

function normalize(value) {
  return String(value ?? '').trim().replace(/\s+/g, ' ').toLowerCase();
}

export function normalizeAutoPasswordType(value) {
  const normalized = normalize(value);
  const match = AUTO_PASSWORD_TYPES.find((item) =>
    item.id === normalized || item.label.toLowerCase() === normalized ||
    item.aliases.some((alias) => alias.toLowerCase() === normalized));
  return match?.id ?? null;
}

export function getAutoPasswordTypeLabel(value) {
  return AUTO_PASSWORD_TYPES.find((item) => item.id === value)?.label ?? 'Unknown';
}

export function detectAccountType(account) {
  // These are explicit provider fields only. Age, username patterns, stock,
  // or other heuristics are intentionally not used to guess a type.
  const raw = [
    account?.type,
    account?.accountType,
    account?.account_type,
    account?.category,
    account?.productType,
    account?.product_type,
  ].find((value) => value !== undefined && value !== null && String(value).trim());
  return normalizeAutoPasswordType(raw);
}

function counters() {
  return { generated: 0, changed: 0, failed: 0, unknown: 0 };
}

function channelRecord(channelId, type) {
  return {
    channelId,
    type,
    enabled: true,
    paused: false,
    counters: counters(),
    pending: [],
    seen: {},
    results: [],
  };
}

function guildRecord(guildId) {
  state.guilds ??= {};
  state.guilds[guildId] ??= {
    channels: {},
    healthMessageId: null,
    healthChannelId: null,
  };
  const guild = state.guilds[guildId];
  guild.channels ??= {};
  guild.healthChannelId ??= getHealthChannel(guildId);
  return guild;
}

function migrateLegacyChannel(guildId) {
  const guild = guildRecord(guildId);
  if (Object.keys(guild.channels).length) return guild;
  const legacy = getAutoPasswordConfig(guildId);
  const legacyType = legacy.types?.length ? normalizeAutoPasswordType(legacy.types[0]) : null;
  if (legacy.enabled && legacy.channelId && legacyType) {
    guild.channels[legacy.channelId] = channelRecord(legacy.channelId, legacyType);
    try { saveState(); } catch (error) {
      console.error('Could not migrate legacy Auto Password settings:', error.message);
    }
  }
  return guild;
}

function publicChannel(channel) {
  return {
    channelId: channel.channelId,
    type: channel.type,
    typeLabel: getAutoPasswordTypeLabel(channel.type),
    enabled: Boolean(channel.enabled),
    paused: Boolean(channel.paused),
    counters: { ...counters(), ...(channel.counters ?? {}) },
    pending: channel.pending?.length ?? 0,
  };
}

export function getAutoPasswordChannels(guildId) {
  const guild = migrateLegacyChannel(guildId);
  return Object.values(guild.channels)
    .filter((channel) => channel.enabled)
    .map(publicChannel);
}

export function getAutoPasswordChannel(guildId, channelId) {
  const guild = migrateLegacyChannel(guildId);
  const channel = guild.channels[channelId];
  return channel?.enabled ? channel : null;
}

export function getAutoPasswordSummary(guildId) {
  const channels = getAutoPasswordChannels(guildId);
  const totals = counters();
  for (const channel of channels) {
    for (const key of Object.keys(totals)) totals[key] += channel.counters[key] ?? 0;
  }
  return {
    channels,
    totals,
    activeChannels: channels.filter((channel) => !channel.paused).length,
    outputChannels: {
      generator: getDeliveryChannel(guildId),
      newPassword: getNewPasswordChannel(guildId),
      health: getHealthChannel(guildId),
    },
  };
}

export function isAutoPasswordEnabledForType(guildId, type) {
  const typeId = normalizeAutoPasswordType(type);
  if (!typeId) return false;
  return getAutoPasswordChannels(guildId).some(
    (channel) => channel.enabled && !channel.paused && channel.type === typeId,
  );
}

export function findAutoPasswordChannelForType(guildId, type) {
  const typeId = normalizeAutoPasswordType(type);
  if (!typeId) return null;
  const guild = migrateLegacyChannel(guildId);
  return Object.values(guild.channels).find(
    (channel) => channel.enabled && !channel.paused && channel.type === typeId,
  ) ?? null;
}

export function configureAutoPasswordChannel(guildId, channelId, type) {
  requireSecureStorage();
  if (!guildId || !channelId) return false;
  const typeId = normalizeAutoPasswordType(type);
  if (!typeId) return false;
  const guild = guildRecord(guildId);
  const existing = guild.channels[channelId];
  guild.channels[channelId] = existing
    ? { ...existing, type: typeId, enabled: true }
    : channelRecord(channelId, typeId);
  saveState();
  return true;
}

export function pauseAutoPasswordChannel(guildId, channelId, paused) {
  const guild = guildRecord(guildId);
  const channel = guild.channels[channelId];
  if (!channel?.enabled) return false;
  channel.paused = Boolean(paused);
  saveState();
  return true;
}

export function removeAutoPasswordChannel(guildId, channelId) {
  const guild = guildRecord(guildId);
  if (!guild.channels[channelId]) return false;
  delete guild.channels[channelId];
  saveState();
  return true;
}

export function setAutoPasswordHealthMessage(guildId, messageId) {
  const guild = guildRecord(guildId);
  guild.healthMessageId = messageId ?? null;
  saveState();
}

export function getAutoPasswordHealthMessage(guildId) {
  return guildRecord(guildId).healthMessageId ?? null;
}

function safe(value, fallback = '—') {
  const text = String(value ?? '').replaceAll('`', 'ˋ').replaceAll('\n', ' ').trim();
  return text ? text.slice(0, 900) : fallback;
}

function statusPayload({
  username,
  type,
  status,
  reason,
  guildId,
  channelId = null,
  exportChannelId = null,
}) {
  const embed = new EmbedBuilder()
    .setTitle('🤖 Kazu Bot — Auto Password')
    .setColor(status === '✅ Completed' ? 0x57f287 : status === '❌ Failed' ? 0xed4245 : 0xfee75c)
    .addFields(
      { name: '👤 Account', value: `\`${safe(username)}\``, inline: true },
      { name: '📊 Type', value: safe(getAutoPasswordTypeLabel(type), 'Unknown'), inline: true },
      { name: '📍 Channel', value: channelId ? `<#${channelId}>` : '—', inline: true },
      { name: '🔄 Status', value: status, inline: false },
    );
  if (reason) embed.addFields({ name: 'Reason', value: safe(reason, 'Unknown error') });
  const components = exportChannelId && status === '✅ Completed'
    ? [new ActionRowBuilder().addComponents(
      new ButtonBuilder()
        .setCustomId(`autopass-export:${exportChannelId}`)
        .setLabel('Export Results')
        .setEmoji('📄')
        .setStyle(ButtonStyle.Secondary),
    )]
    : [];
  return { embeds: [embed], components };
}

async function resolveOutputChannel(client, guildId, fallbackChannelId) {
  const configured = getNewPasswordChannel(guildId) || fallbackChannelId;
  if (!configured) return null;
  const channel = await client.channels.fetch(configured).catch(() => null);
  return channel?.isTextBased?.() ? channel : null;
}

async function processJob(client, guildId, channel, job) {
  let processingMessage = null;
  try {
    const output = await resolveOutputChannel(client, guildId, channel.channelId);
    if (output) {
      processingMessage = await output.send(statusPayload({
        username: job.username,
        type: job.type,
        status: '🔄 Processing...',
        guildId,
        channelId: channel.channelId,
      })).catch(() => null);
    }

    const newPassword = createRandomPassword();
    await changePassword({
      cookie: job.account.cookie,
      currentPassword: job.currentPassword,
      newPassword,
    });
    // The mutation response and a follow-up authenticated session check are
    // both required before Changed is incremented.
    const confirmed = await verifyPasswordChange(job.account.cookie);
    if (!confirmed) throw new Error('The account-management system did not confirm the password change.');

    const updatedAccount = {
      ...job.account,
      password: newPassword,
      type: getAutoPasswordTypeLabel(job.type),
      passwordChangeStatus: 'Automatically changed and verified',
    };
    try {
      setUpdatedAccount(updatedAccount);
    } catch (error) {
      console.error('Could not persist updated Auto Password credentials:', error.message);
    }
    try {
      recordPasswordChange(updatedAccount);
    } catch (error) {
      console.error('Could not persist Auto Password history:', error.message);
    }

    channel.counters.changed++;
    channel.seen[job.key] = { status: 'changed', jobId: job.jobId };
    channel.results.push({
      username: updatedAccount.username,
      password: newPassword,
      type: job.type,
      jobId: job.jobId,
      timestamp: new Date().toISOString(),
    });
    channel.results = channel.results.slice(-1000);
    saveState();
    if (processingMessage) {
      await processingMessage.edit(statusPayload({
        username: job.username,
        type: job.type,
        status: '✅ Completed',
        guildId,
        channelId: channel.channelId,
        exportChannelId: channel.channelId,
      })).catch(() => {});
    }
    return { account: updatedAccount, changed: true, error: null };
  } catch (error) {
    channel.counters.failed++;
    channel.seen[job.key] = { status: 'failed', jobId: job.jobId };
    saveState();
    if (processingMessage) {
      await processingMessage.edit(statusPayload({
        username: job.username,
        type: job.type,
        status: '❌ Failed',
        reason: error.message,
        guildId,
        channelId: channel.channelId,
      })).catch(() => {});
    }
    return {
      account: job.account,
      changed: false,
      error: error.message || 'Password change failed.',
    };
  }
}

async function runWorker(client, guildId, channelId) {
  const key = `${guildId}:${channelId}`;
  if (workers.has(key)) return workers.get(key);
  const loop = (async () => {
    try {
      while (true) {
        const channel = getAutoPasswordChannel(guildId, channelId);
        if (!channel || channel.paused || !channel.pending.length) break;
        const job = channel.pending[0];
        job.status = 'processing';
        saveState();
        const result = await processJob(client, guildId, channel, job);
        channel.pending.shift();
        saveState();
        const resolve = waiters.get(job.jobId);
        waiters.delete(job.jobId);
        resolve?.(result);
        void refreshHealth(client, guildId);
      }
    } catch (error) {
      console.error(`Auto Password worker failed for ${guildId}/${channelId}:`, error.message);
    } finally {
      workers.delete(key);
      const channel = getAutoPasswordChannel(guildId, channelId);
      if (channel && !channel.paused && channel.pending.length) void runWorker(client, guildId, channelId);
    }
  })();
  workers.set(key, loop);
  return loop;
}

function createRandomPassword() {
  const letters = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
  const digits = '23456789';
  const bytes = randomBytes(4);
  return `KazuShop${digits[bytes[0] % digits.length]}${letters[bytes[1] % letters.length]}${digits[bytes[2] % digits.length]}${letters[bytes[3] % letters.length]}`;
}

function enqueue(client, {
  guildId,
  type,
  account,
  ownerId,
  currentPassword,
  channelId = null,
  source = 'manual',
}) {
  requireSecureStorage();
  const target = channelId
    ? getAutoPasswordChannel(guildId, channelId)
    : findAutoPasswordChannelForType(guildId, type);
  if (!target) return Promise.resolve({
    account,
    changed: false,
    accepted: false,
    error: 'No enabled Auto Password channel is configured for this account type.',
  });
  if (!account?.username || !account?.cookie || !currentPassword) {
    return Promise.resolve({
      account,
      changed: false,
      accepted: false,
      error: 'The authorized account-management system did not provide complete credentials.',
    });
  }

  const key = normalize(account.username);
  if (target.seen[key]) return Promise.resolve({
    account,
    changed: false,
    accepted: false,
    duplicate: true,
    error: 'This account was already accepted by this Auto Password channel.',
  });

  const job = {
    jobId: randomUUID(),
    key,
    username: String(account.username),
    type: normalizeAutoPasswordType(type),
    account: { ...account },
    currentPassword: String(currentPassword),
    ownerId: ownerId ?? null,
    source,
    status: 'queued',
    acceptedAt: new Date().toISOString(),
  };
  target.seen[key] = { status: 'queued', jobId: job.jobId };
  target.pending.push(job);
  target.counters.generated++;
  saveState();
  const result = new Promise((resolve) => waiters.set(job.jobId, resolve));
  void runWorker(client, guildId, target.channelId);
  return result.then((value) => ({ ...value, accepted: true }));
}

export function submitGeneratedAccount({ client, guildId, type, account, ownerId }) {
  return enqueue(client, {
    guildId,
    type,
    account,
    ownerId,
    currentPassword: account?.password,
    source: 'generated',
  });
}

async function lookupAuthorizedAccount(username) {
  return getUpdatedAccount(username) ?? await findAccountByUsername(username);
}

function parseInput(content) {
  const valid = [];
  let invalid = 0;
  for (const rawLine of String(content ?? '').split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line) continue;
    const separator = line.indexOf(':');
    if (separator < 1 || separator === line.length - 1) {
      invalid++;
      continue;
    }
    const username = line.slice(0, separator).trim();
    const password = line.slice(separator + 1).trim();
    if (!username || !password || username.length > 64 || password.length > 200) {
      invalid++;
      continue;
    }
    valid.push({ username, password });
  }
  return { valid, invalid };
}

async function readMessageInput(message) {
  const parts = [message.content || ''];
  const attachment = message.attachments?.find?.((item) =>
    String(item.name || '').toLowerCase().endsWith('.txt'));
  if (attachment?.url) {
    try {
      const response = await fetch(attachment.url);
      if (response.ok) {
        const bytes = await response.arrayBuffer();
        if (bytes.byteLength <= 1024 * 1024) parts.push(Buffer.from(bytes).toString('utf8'));
      }
    } catch (error) {
      console.error('Could not read Auto Password TXT input:', error.message);
    }
  }
  return parts.filter(Boolean).join('\n');
}

export async function processAutoPasswordInput(message, client, content = null) {
  const channel = getAutoPasswordChannel(message.guildId, message.channelId);
  if (!channel) return { handled: false };
  const parsed = parseInput(content ?? await readMessageInput(message));
  if (!parsed.valid.length && !parsed.invalid) return { handled: false };

  // Remove the source message before any network lookup. Credentials never
  // remain visible in the Discord channel.
  await message.delete().catch(() => {});
  if (!message.member?.permissions?.has?.(PermissionFlagsBits.ManageGuild)) {
    return { handled: true, accepted: 0, invalid: parsed.invalid };
  }

  let accepted = 0;
  let unknown = 0;
  let mismatched = 0;
  for (const item of parsed.valid) {
    try {
      const account = await lookupAuthorizedAccount(item.username);
      const type = detectAccountType(account);
      const key = normalize(item.username);
      if (!type) {
        if (!channel.seen[key]) {
          channel.seen[key] = { status: 'unknown' };
          channel.counters.unknown++;
          unknown++;
          saveState();
          const output = await resolveOutputChannel(client, message.guildId, message.channelId);
          if (output) {
            await output.send(statusPayload({
              username: item.username,
              type: null,
              status: '⚠️ Unknown',
              reason: 'The authorized account-management system did not provide an explicit account type.',
              guildId: message.guildId,
              channelId: message.channelId,
            })).catch(() => {});
          }
        }
        continue;
      }
      if (channel.type !== type) {
        mismatched++;
        continue;
      }
      if (!account?.cookie) {
        mismatched++;
        continue;
      }
      const result = await enqueue(client, {
        guildId: message.guildId,
        channelId: message.channelId,
        type,
        account,
        ownerId: message.author.id,
        currentPassword: item.password,
      });
      if (result.accepted) accepted++;
    } catch (error) {
      console.error(`Auto Password input failed for ${item.username}:`, error.message);
    }
  }
  if (parsed.invalid || unknown || mismatched) {
    const output = await resolveOutputChannel(client, message.guildId, message.channelId);
    if (output) {
      const parts = [];
      if (accepted) parts.push(`accepted ${accepted}`);
      if (parsed.invalid) parts.push(`ignored ${parsed.invalid} invalid`);
      if (unknown) parts.push(`${unknown} unknown`);
      if (mismatched) parts.push(`${mismatched} not routed`);
      await output.send(`⚠️ Auto Password: ${parts.join(' · ')}. Credentials were not displayed.`).catch(() => {});
    }
  }
  return { handled: true, accepted, invalid: parsed.invalid, unknown, mismatched };
}

export function buildAutoPasswordExport(guildId, channelId = null) {
  const guild = migrateLegacyChannel(guildId);
  const channels = channelId ? [guild.channels[channelId]] : Object.values(guild.channels);
  const results = channels
    .filter(Boolean)
    .flatMap((channel) => channel.results ?? [])
    .filter((result) => result.username && result.password);
  const unique = [...new Map(results.map((result) => [normalize(result.username), result])).values()];
  const content = unique.map((result) => `${result.username}:${result.password}`).join('\n');
  if (!content) return { accounts: [], file: null };
  return {
    accounts: unique,
    file: new AttachmentBuilder(Buffer.from(`${content}\n`, 'utf8'), {
      name: 'kazu-auto-password-results.txt',
    }),
  };
}

async function refreshHealth(client, guildId) {
  try {
    const { updateHealthMessage } = await import('./health.js');
    await updateHealthMessage(client, guildId);
  } catch (error) {
    console.error('Could not refresh Auto Password health:', error.message);
  }
}

export async function restoreAutoPasswordQueues(client) {
  for (const guildId of Object.keys(state.guilds ?? {})) {
    const guild = migrateLegacyChannel(guildId);
    for (const channel of Object.values(guild.channels)) {
      if (channel.enabled && !channel.paused && channel.pending?.length) {
        void runWorker(client, guildId, channel.channelId);
      }
    }
  }
}

export function buildAutoPasswordHealth(guildId, lastUpdate = new Date()) {
  const summary = getAutoPasswordSummary(guildId);
  return {
    activeChannels: summary.activeChannels,
    totals: summary.totals,
    lastUpdate,
  };
}